CAP_CPU = 4096
CAP_MEM = 8192

TASKS = [
    ("api", 1024, 2048),
    ("worker", 2048, 4096),
    ("cron", 512, 1024),
    ("cache", 1024, 3072),
]

def place_tasks(tasks):
    instances = []  # each: {"name": ..., "cpu": used, "mem": used}
    placements = []
    for name, cpu, mem in tasks:
        target = None
        for inst in instances:
            if inst["cpu"] + cpu <= CAP_CPU and inst["mem"] + mem <= CAP_MEM:
                target = inst
                break
        if target is None:
            target = {"name": f"instance-{len(instances) + 1}", "cpu": 0, "mem": 0}
            instances.append(target)
        target["cpu"] += cpu
        target["mem"] += mem
        placements.append((name, target["name"]))
    return placements

result = place_tasks(TASKS)
for task, inst in result:
    print(f"{task} -> {inst}")
print(f"instances_used={len({inst for _, inst in result})}")
